    {
        public readonly string CompanionId, Name, Requirement, BodySource;
        public readonly SkillMechanic Mechanic;
        public readonly bool Protection;
        public readonly int TuningIndex;
        public SkillProfile Tuning => CompanionSkillTuning.Profiles[TuningIndex];
