            new CompanionSkillDefinition("PianoCrocodile", "Chord Slam", SkillMechanic.Eruption, false, 116, "slams a keyboard line: waves of damage travel along the line, one per second. Bond tie: chords are Beats", "a crocodile whose jaws are piano keys"),
            new CompanionSkillDefinition("NewtonApple", "Falling Fruit", SkillMechanic.Eruption, false, 117, "apples fall on clusters and split into smaller apples that roll. Bond tie: apples are small masses", "a red apple with a small leaf hat"),
            new CompanionSkillDefinition("BowlingSloth", "Strike", SkillMechanic.Dash, false, 118, "rolls through a line, bowling enemies over, and shields the friends it passes (6%). Bond tie: bowling counts Mass", "a sloth curled into a bowling ball"),
            new CompanionSkillDefinition("SatelliteBee", "Satellite Strike", SkillMechanic.Eruption, false, 119, "marks a ground zone (solid filled) and a laser sweeps through it. Bond tie: the zone draws enemies together", "a bee with satellite dishes on its wings"),
        };
        private static readonly Dictionary<string, CompanionSkillDefinition> byId = Build();
        private static Dictionary<string, CompanionSkillDefinition> Build()
        {
            var result=new Dictionary<string, CompanionSkillDefinition>(StringComparer.Ordinal);
            for(int i=0;i<All.Length;i++) result.Add(All[i].CompanionId,All[i]);
            return result;
        }
        public static bool TryGet(string id, out CompanionSkillDefinition definition)
        { return byId.TryGetValue(id, out definition); }
    }
